INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x114-cougar', 1, 'NG-314 Shoulder Tri-Barrel Blaster (1)', '2D6 M.D. single blast, 4D6 M.D. dual blast, 6D6 M.D. triple blast (simultaneous, at one target)', 1, '1,600 ft (488 m)', 'Each single or multiple blast counts as one melee attack', 'Effectively unlimited; drawn from the suit''s power supply', NULL, 'Assault and anti-personnel, secondarily defense. A three-barrel laser on top of the right shoulder. It can be swapped for an S.D.C. machine-gun-style slug thrower: 1,200 ft (366 m), 6D6+6 S.D.C. per six-round burst, 360 rounds (60 bursts) of standard, silver-coated or wooden ammunition from a drum under the backpack.'),
  ('ng-x114-cougar', 2, 'NG-X114 Forearm Ion Blaster (1)', '3D6 M.D. per blast', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault and anti-personnel, secondarily defense. A short-range point-and-shoot ion blaster in the right forearm.'),
  ('ng-x114-cougar', 3, 'NG-XG114 Shoulder Grenade Launchers (2)', 'By grenade: fragmentation 3D6 M.D. to a 12 ft (3.7 m) radius; high explosive/armor piercing 4D6 M.D. to 3 ft (0.9 m); plasma 6D6 M.D. to 5 ft (1.5 m); smoke, tear gas, stun/flash and Hex do no damage', 1, '600 ft (183 m)', 'Single shot or volleys of 2, 3 or 4; each grenade or volley counts as one melee attack', '8; four per launcher. Reloaded by hand at one melee round (15 seconds) per launcher; spares ride in the backpack, pouches or a 24-grenade M.D.C. case', NULL, 'Anti-monster and anti-armor, secondarily anti-personnel and wall breaching. Low-profile launchers between the neck and each shoulder, used on troops and fortifications, to open or close an entrance, and to burn out Xiticix eggs and nests. Special grenades: smoke fills a 40 ft (12.2 m) radius; tear gas 25 ft (7.6 m), unprotected victims -10 to strike, parry and dodge, -3 on initiative and one attack lost while inside and 1D6+1 rounds after; stun/flash 4 ft (1.2 m), -10 to strike, parry and dodge, -1 initiative and one attack lost for 1D4 rounds; Hex (Northern Gun One p.138) a 20 ft (6.1 m) acidic cloud lasting 1D4+3 rounds that costs mortals 2 attacks, -6 Perception, -4 initiative, -2 to strike, parry, dodge and disarm, half Spd and -20% on skills, supernatural beings half those penalties.'),
  ('ng-x114-cougar', 4, 'Secondary Grenade Launchers (6)', 'As the shoulder launchers, by grenade type', 1, '600 ft (183 m)', 'Single shot or volleys of 2 or 3; each grenade or volley counts as one melee attack', '6; three in each side of the chest. Reloading all six by hand takes one melee round (15 seconds)', NULL, 'Anti-monster and anti-armor, secondarily anti-personnel and wall breaching. Tube launchers behind a plate that pops off on each side of the chest.'),
  ('ng-x114-cougar', 5, 'Large Forearm Vibro-Blades (2)', '2D6 M.D. per Vibro-Sword; 4D6 M.D. for a strike with both', 1, 'Melee', NULL, NULL, NULL, 'Assault and anti-personnel, secondarily defense. A twin pair, most often on the left forearm. Even retracted they reach past the fingers, for parrying, slashing and backhand strikes; they slide forward behind the wrist for reach, and can fold forward or back, stand upright, or lie flat beside the forearm blaster.'),
  ('ng-x114-cougar', 6, 'Vibro-Claws (20)', 'Hand: full five-claw strike 6D6 M.D., one blade 1D6 M.D., two blades 2D6 M.D. Foot: five-claw kick 6D6+6 M.D., big-toe blade alone 2D4+4 M.D. (Robotic P.S. included)', 1, 'Melee', NULL, NULL, NULL, 'Assault and anti-personnel, secondarily defense. Retractable claws in every finger and toe that grip hive walls when climbing and slash, stab and tear in a fight.'),
  ('ng-x114-cougar', 7, 'Cougar Forearm Flamethrower', '3D6 M.D. to the target and anyone within 10 ft (3 m), double to beings vulnerable to fire; 1D6 M.D. on diesel or gasoline', 1, '80 ft (24.4 m)', 'Each burst counts as one melee action/attack', '3 bursts from a 6 gallon (22.7 liter) reserve of military napalm', NULL, 'Anti-structure and anti-personnel, secondarily anti-monster. Printed as the standard left forearm weapon: a small unit under the forearm or on top of it between the Vibro-Swords, fed by a hose from a tank at the backpack, which seals itself shut underwater. Victims in a bunker, cave or unsealed vehicle without their own air save vs poison or pass out for 1D4 melee rounds. 50,000 credits as an alternative modular attachment (gear row ng-x114-cougar-forearm-flamethrower).'),
  ('ng-x32-coyote', 1, 'NG-X132 "Deathmark" Dual Sniper Rifle', 'Laser 3D6 M.D.; ion beam 4D6+2 M.D.; per single shot', 1, 'Laser 2,000 ft (610 m); ion beam 1,200 ft (366 m)', 'Each blast counts as one melee attack; the laser or the ion beam, never both at once', '20 laser blasts per standard E-Clip (in the handle); 10 ion blasts per E-Clip (in the stock)', '+1 to strike on an Aimed/Called Shot', 'Precision shooting and targeting, secondarily assault. A handheld over-under rifle exclusive to the Coyote: ion rifle on top, laser below, both single-shot. Well balanced, with a telescopic passive nightvision scope (2,000 ft/610 m) and a removable sling; meant for sniping and for picking off sensor pods, tires and antennas. Not sold without the armor; on the secondary market 35,000-50,000 credits, poor availability (gear row ng-x132-deathmark-dual-sniper-rifle).'),
  ('ng-x32-coyote', 2, 'Forearm Laser (1, right)', '2D6 M.D. per single shot', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited; drawn from the suit''s power supply', NULL, 'Assault and sabotage, secondarily defense. A light, low-profile short-range laser, usually in the right forearm, for close fighting, sabotage and self-defense.'),
  ('ng-x32-coyote', 3, 'Forearm Vibro-Blade (1, left)', '1D6 M.D.', 1, 'Arm''s length; melee', NULL, NULL, NULL, 'A small blade in the other forearm, usually the left, for cutting, sabotage and close fighting.'),
  ('ng-x11-delilah', 1, 'NG-MML11-12 Storm Mini-Missile Launcher (1, right shoulder)', 'By missile; usually plasma 1D6x10 M.D. or armor piercing/heat 1D4x10 M.D., though any type can be loaded', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6', '12. A second person reloads by hand from the suit''s back, six missiles per two melee rounds (30 seconds)', NULL, 'Anti-aircraft, anti-missile and assault, secondarily anti-armor and defense. Fires straight up or through a 90 degree forward arc; it stows on the back like a Glitter Boy''s Boom Gun and can fire stowed or swing forward on a voice command.'),
  ('ng-x11-delilah', 2, 'NG-X2-11 Plasma Ejectors (2)', '4D6 M.D. single shot; 1D4x10 M.D. dual blast from both arms at one target', 1, '1,000 ft (305 m)', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily close combat and defense. Point-and-shoot plasma ejectors, one on each forearm.'),
  ('ng-x11-delilah', 3, 'NG-X1-11 Ion Blaster (1, head)', '3D6 M.D. single blast; 1D4x10 M.D. multiple pulse', 1, '1,200 ft (366 m)', 'Each blast or pulse counts as one melee attack/action', 'Effectively unlimited on nuclear and Solid Oxide suits; 45 blasts (15 pulses) on electric battery', NULL, 'Anti-personnel, secondarily assault. A hands-free blaster in the helmet crest (the cyclopean eye on the Del) that fires wherever the head points.'),
  ('ng-x11-delilah', 4, 'Forearm Vibro-Blades (2)', '2D6+1 M.D. per attack; 4D6+2 M.D. stab/impaling power punch (two attacks); Robot P.S. included', 1, 'Melee', NULL, NULL, NULL, 'Assault and close combat, secondarily defense and climbing. Retractable, one under each plasma ejector.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-x114-cougar', 'ng-x32-coyote', 'ng-x11-delilah');
SELECT 'their 35 locations are in' AS assertion, count(*) AS got, 35 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x114-cougar', 'ng-x32-coyote', 'ng-x11-delilah');
SELECT 'their 14 weapon entries are in' AS assertion, count(*) AS got, 14 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x114-cougar', 'ng-x32-coyote', 'ng-x11-delilah');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x114-cougar', 'ng-x32-coyote', 'ng-x11-delilah') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

